            var reservation = reservations.find(reservationId(ctx));
            var room = rooms.find(reservation.roomNumber()).orElseThrow();
            ctx.json(ReservationResponse.of(reservation, room));
        });
        server.post("/reservations/{id}/confirmation", ctx -> {
            var reservation = reservations.confirm(reservationId(ctx));
            var room = rooms.find(reservation.roomNumber()).orElseThrow();
            ctx.json(ReservationResponse.of(reservation, room));
        });
        server.post("/reservations/{id}/cancellation", ctx -> {
            var reservation = reservations.cancel(reservationId(ctx));
            var room = rooms.find(reservation.roomNumber()).orElseThrow();
