            var room = rooms.find(reservation.roomNumber()).orElseThrow();
            ctx.json(ReservationResponse.of(reservation, room));
        });
        server.post("/reservations/{id}/check-out", ctx ->
                ctx.json(reservations.checkOut(reservationId(ctx))));
